    start_ms integer,
    end_ms integer,
    language text,
    text text NOT NULL,
    text_norm text NOT NULL,
    text_stem text DEFAULT ''::text NOT NULL,
    tsv tsvector GENERATED ALWAYS AS ((setweight(to_tsvector('simple'::regconfig, text_norm), 'A'::"char") || setweight(to_tsvector('simple'::regconfig, text_stem), 'B'::"char"))) STORED,
    token_estimate integer NOT NULL,
    content_hash text NOT NULL,
    transcript_version integer DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
